// Normalize incoming message from Meta WhatsApp Cloud Webhook or Demo Console
const item = $input.first().json;

let senderPhone = item.phone || item.from || '919876543210';
let senderName = item.name || 'Customer';
let messageText = item.text || item.message || '';

// Check Meta Cloud Webhook structure
if (item.entry && item.entry[0] && item.entry[0].changes && item.entry[0].changes[0].value) {
    const val = item.entry[0].changes[0].value;
    if (val.messages && val.messages[0]) {
        senderPhone = val.messages[0].from;
        messageText = val.messages[0].text?.body || '';
        if (val.contacts && val.contacts[0]) {
            senderName = val.contacts[0].profile?.name || 'Customer';
        }
    }
}

return [{
    json: {
        chatInput: messageText,
        senderPhone: senderPhone,
        senderName: senderName,
        timestamp: new Date().toISOString()
    }
}];
